         (enforced=^^check(false), \"nrows(t2) is equal to nrows(t1) + \
         length(rs)\")\n\
         ],\n\
         operation=let addRows = typfun row ->  fun (r :row, rs : [row]) -> rs \
         @ [r]  in addRows,\n\
